#include <stdio.h>

int main(void) {
    char name[50];

    printf("Enter your name: ");
    fgets(name, sizeof(name), stdin);   // safe: won't overflow the buffer

    // fgets keeps the trailing newline -- strip it if present
    size_t len = strlen(name);
    if (len > 0 && name[len - 1] == '\n') {
        name[len - 1] = '\0';
    }

    printf("Hello, %s!\n", name);
    return 0;
}
